INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('human-cannonball', 17025, '1978-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co986t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8x1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Human Cannonball', 'In Human Cannonball your goal is to fire a man out of a cannon and have him land in a bucket of water. To do this you need to adjust your cannon so the position, angle, and firing speed are just right. You score a point for each successful landing, and the game ends after seven attempts. Several game variations are included which allow you to have the position, angle and speed all set by the player, or have one or more of these in a fixed position, or have one or more of these randomly set by the computer. If you wish to make the game more challenging, you can also set a moving wall in front of the bucket which will make your timing more critical.' FROM games WHERE igdb_id = 17025 ON CONFLICT (game_id, language_code) DO NOTHING;
