INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Basketball', 'Basketball is an Atari 2600 game loosely based on the sport of the same name. The game features a simple game of one-on-one basketball playable by one or two players, one of the few early Atari 2600 to have a true single player feature with an AI-controlled opponent.' FROM games WHERE igdb_id = 18407 ON CONFLICT (game_id, language_code) DO NOTHING;
