INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-breakout', 12321, '1978-09-21', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co671n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arxsg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Breakout', 'Super Breakout is an arcade game released by Atari in 1978. It utilizes a Motorola M6502 (running up at 375 KHz) and, as the name suggests, is the sequel to Breakout, which was released two years earlier. There are three different modes to choose from: Double Breakout, the playfield for which contains in fifty-two orange blocks (5-14 points), fifty-two green blocks (1-6 points), two paddles and two balls, Cavity Breakout, which contains in forty-four orange blocks (7-21 points), and fifty-two green blocks (1-9 points), one paddle, and three balls (the second and third of which have to be freed before they come into play) and Progressive Breakout which contains fifty-two blue blocks (7 points) and fifty-two green blocks (5 points), one paddle, and one ball - and the blocks shall be lowered down towards the paddle, at a rate determined by the number of times the ball lands on your paddle, but as the ball destroys them, additional rows of blocks shall appear at the top of the screen and be lowered down towards the paddle at an increasing rate. This is also the only mode for which it''s possible for a player to receive an infinite amount of points by playing, but the score display shall roll over at 10000.' FROM games WHERE igdb_id = 12321 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 12321 AND ge.slug = 'arcade' ON CONFLICT DO NOTHING;
