INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Truck', 'Players must cooperate to drive the truck through traffic as far as possible without crashing. While the game can be played with one player, it was primarily designed for two. The front player steers the tractor of the truck sitting down, controlling the gas and brakes, while the rear player stands, and steers the tiller for the rear wheels, controlling the swing of the trailer. The cabinet also provides the players with bells and horns, although these have no use in the actual game.' FROM games WHERE igdb_id = 143172 ON CONFLICT (game_id, language_code) DO NOTHING;
