INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Home Run', 'This is the first of three iterations of baseball from Atari and is the most simple. The pitcher pitches and controls the direction of the ball. The batter hits and keeps running until he''s made to stop. There are up to 3 defensive players that can try to get the batter out after he hits. All hits are grounders and defensive players can''t throw the ball.' FROM games WHERE igdb_id = 18414 ON CONFLICT (game_id, language_code) DO NOTHING;
